namespace FileSort.Generator.Content.Words;

/// <summary>
/// The built-in dictionary that Strings are composed from: exactly 1024 distinct lower-case words of the letters a to
/// z, so a word index is 10 random bits. The list was written for this project. Words with apostrophes or hyphens are
/// left out, because culture-aware comparers treat them specially and a default file must sort the same way under
/// every comparer. The list is part of the content version: changing it changes the generated bytes.
/// </summary>
internal static class Dictionary
{
    /// <summary>The number of words.</summary>
    public const int WordCount = 1024;

    /// <summary>The number of random bits that select a word.</summary>
    public const int IndexBits = 10;

    /// <summary>The length of the longest word allowed in the list, in bytes.</summary>
    public const int MaxWordLength = 12;

    /// <summary>
    /// Every word occupies a slot of this size, padded with zeros, so a word can be copied as one fixed-size block
    /// whatever its length.
    /// </summary>
    public const int SlotSize = 16;

    private static readonly byte[] SlotTable = new byte[WordCount * SlotSize];

    private static readonly byte[] LengthTable = new byte[WordCount];

    static Dictionary()
    {
        ReadOnlySpan<byte> source = Source;
        int index = 0;
        foreach (Range range in source.Split((byte)' '))
        {
            ReadOnlySpan<byte> word = source[range];
            if (index >= WordCount || word.Length is 0 or > MaxWordLength)
            {
                throw new InvalidOperationException("The built-in dictionary is malformed.");
            }

            word.CopyTo(SlotTable.AsSpan(index * SlotSize));
            LengthTable[index] = (byte)word.Length;
            index++;
        }

        if (index != WordCount)
        {
            throw new InvalidOperationException("The built-in dictionary is malformed.");
        }
    }

    /// <summary>All slots, one after another.</summary>
    public static ReadOnlySpan<byte> Slots => SlotTable;

    /// <summary>The length of every word in bytes.</summary>
    public static ReadOnlySpan<byte> Lengths => LengthTable;

    /// <summary>The bytes of one word.</summary>
    public static ReadOnlySpan<byte> Word(int index)
    {
        return SlotTable.AsSpan(index * SlotSize, LengthTable[index]);
    }

